I had to use something like this to ensure the padding stays consistent:
MiniPick.win_size = function()
    local height = math.floor(0.35 * vim.o.lines)
    local width = math.floor(0.75 * vim.o.columns)

    local config = {
        anchor = "NE",
        height = height,
        width = width,
        border = "rounded",
        row = math.floor(0.55 * vim.o.lines),
        col = math.floor(0.88 * vim.o.columns),
    }
    return config
end
local VimResize = vim.schedule_wrap(function()
    MiniPick.set_picker_opts({
        window = {
            config = MiniPick.win_size(),
        },
    })
    vim.cmd [[redraw!]]
end)
vim.api.nvim_create_autocmd("VimResized", {
    pattern = "*",
    callback = VimResize,
})
